<script setup lang="ts">import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import SearchInput from '@/components/zs/SearchInput.vue';import Toolbar from '@/components/zs/Toolbar.vue';import ZButton from '@/components/zs/ZButton.vue';import PipelineBoard from '@/components/crm/PipelineBoard.vue';import {useCrmData} from '@/composables/useCrmData';import type {LeadStage} from '@/types/crm';import {showToast} from '@/composables/useToast';import {crmRepository} from '@/services/crm/repository';import {setPageMeta} from '@/lib/page-meta';setPageMeta('CRM Pipeline','Manage opportunities across the sales pipeline.');function notify(message:string){showToast('Pipeline settings',message,'info')}async function move(id:string,stage:LeadStage){local.value[id]=stage;await crmRepository.updateLeadStage(d.activeCompanyId.value,id,stage);showToast('Stage updated',`Opportunity moved to ${stage}.`)}const d=useCrmData(),q=ref(''),owner=ref('All owners'),local=ref<Record<string,LeadStage>>({}),r=useRouter();const owners=computed(()=>[...new Set((d.leads.data.value??[]).map(x=>x.owner))]);const rows=computed(()=>(d.leads.data.value??[]).map(x=>({...x,stage:local.value[x.id]??x.stage})).filter(x=>(owner.value==='All owners'||x.owner===owner.value)&&(`${x.name} ${x.company}`.toLowerCase().includes(q.value.toLowerCase()))));</script>
<template><AppShell><PageHeader title="Pipeline" description="Drag opportunities between stages; changes are preview-only"><template #actions><ZButton variant="outline" @click="notify('Stage management is ready for the future API. Current defaults remain unchanged.')">Manage stages</ZButton></template></PageHeader><Panel><Toolbar><SearchInput v-model="q" placeholder="Search lead or company"/><select v-model="owner" class="field max-w-48"><option>All owners</option><option v-for="x in owners" :key="x">{{x}}</option></select></Toolbar><div class="p-3"><PipelineBoard :leads="rows" @move="move" @open="id=>r.push(`/crm/leads/${id}`)"/></div></Panel></AppShell></template>
